def is_palindrome(n):
    return str(n) == str(n)[::-1]

def even_odd_palindrome(n):
    evens = 0
    odds = 0
    for i in range(1, n+1):
        if is_palindrome(i) and i % 2 == 0:
            evens += 1
        elif is_palindrome(i) and i % 2 != 0:
            odds += 1
    return (evens, odds)

# Test cases
