def int_to_mini_roman(number):
    roman_numerals = {1: 'i', 5: 'v', 10: 'x', 50: 'l', 100: 'c', 500: 'd', 1000: 'm'}
    numeral = ''
    for num, symbol in roman_numerals.items():
        count = number // num
        number -= count * num
        if count > 3:
            numeral += symbol * (count - 3) + roman_numerals[num * 5] + roman_numerals[num * 10]
        elif count == 3:
            numeral += symbol + roman_numerals[num * 5]
        elif count == 4:
            numeral += symbol + roman_numerals[num * 10]
        elif count > 0:
            numeral += symbol * count
    return numeral
```

